package BaseThread;import static org.junit.jupiter.api.Assertions.*;import java.time.Duration;import java.util.concurrent.*;import org.junit.jupiter.api.Test;
class CosMutexTimeoutTest{@Test void contendedKernelLockFailsWithinConfiguredBudget()throws Exception{ThreadManager.getInstance().setCheckDeadThread(false);var lock=new CosMutex(10,Duration.ofMillis(50));var held=new CountDownLatch(1);var release=new CountDownLatch(1);var owner=Executors.newSingleThreadExecutor();try{var future=owner.submit(()->{lock.lock();held.countDown();try{release.await();}finally{lock.unlock();}return null;});assertTrue(held.await(1,TimeUnit.SECONDS));long started=System.nanoTime();assertThrows(IllegalStateException.class,lock::lock);assertTrue(Duration.ofNanos(System.nanoTime()-started).compareTo(Duration.ofMillis(300))<0);release.countDown();future.get(1,TimeUnit.SECONDS);}finally{release.countDown();owner.shutdownNow();ThreadManager.getInstance().setCheckDeadThread(true);}}}
